+use crate::api::client::ApiClient;
+use crate::constants;
+use crate::models::{ResultWithDefaultError, TimeEntry};
+use crate::utilities;
+use std::collections::HashMap;
+
+const BILLING_UNIT_SECONDS: i64 = 15 * 60;
+
+fn rounded_billable_seconds(entry: &TimeEntry) -> Option<i64> {
+    if !entry.billable || entry.is_running() || entry.stop.is_none() {
+        return None;
+    }
+
+    // Round each entry independently, including entries shorter than one unit.
+    let seconds = entry.duration.max(0);
+    Some(((seconds + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS)
+}
+
+pub struct BillCommand;
+
+impl BillCommand {
+    pub async fn execute(
+        api_client: impl ApiClient,
+        since: Option<String>,
+        until: Option<String>,
+    ) -> ResultWithDefaultError<()> {
+        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
+        let entries = api_client.get_time_entries_filtered(since, until).await?;
+        let mut totals: HashMap<String, i64> = HashMap::new();
+
+        for entry in &entries {
+            if let Some(seconds) = rounded_billable_seconds(entry) {
+                let project = entry
+                    .project
+                    .as_ref()
+                    .map(|project| project.name.clone())
+                    .unwrap_or_else(|| constants::NO_PROJECT.to_string());
+                *totals.entry(project).or_default() += seconds;
+            }
+        }
+
+        if totals.is_empty() {
+            println!("(no data)");
+            return Ok(());
+        }
+
+        let mut totals: Vec<_> = totals.into_iter().collect();
+        totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
+            seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
+        });
+
+        let total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
+        for (project, seconds) in totals {
+            println!("{seconds}s  {project}");
+        }
+        println!("{total}s  Total");
+        Ok(())
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use crate::api::client::MockApiClient;
+    use crate::models::Project;
+    use chrono::{TimeZone, Utc};
+
+    fn entry(duration: i64, billable: bool, stop: bool, project: Option<&str>) -> TimeEntry {
+        let start = Utc.timestamp_opt(1_700_000_000, 0).single().unwrap();
+        TimeEntry {
+            id: duration,
+            description: String::new(),
+            start,
+            stop: stop.then_some(start),
+            duration: if stop { duration } else { -start.timestamp() },
+            billable,
+            workspace_id: 1,
+            tags: vec![],
+            project: project.map(|name| Project {
+                id: 1,
+                name: name.to_string(),
+                workspace_id: 1,
+                client: None,
+                is_private: false,
+                active: true,
+                at: start,
+                created_at: start,
+                color: "#000000".to_string(),
+                billable: None,
+            }),
+            task: None,
+            created_with: None,
+        }
+    }
+
+    #[test]
+    fn rounds_each_entry_up() {
+        assert_eq!(rounded_billable_seconds(&entry(7 * 60, true, true, None)), Some(15 * 60));
+        assert_eq!(rounded_billable_seconds(&entry(22 * 60, true, true, None)), Some(30 * 60));
+        assert_eq!(rounded_billable_seconds(&entry(0, true, true, None)), Some(0));
+        assert_eq!(rounded_billable_seconds(&entry(7 * 60, false, true, None)), None);
+        assert_eq!(rounded_billable_seconds(&entry(7 * 60, true, false, None)), None);
+    }
+
+    #[tokio::test]
+    async fn aggregates_and_sorts_project_totals() {
+        let mut client = MockApiClient::new();
+        client
+            .expect_get_time_entries_filtered()
+            .returning(|_, _| {
+                Ok(vec![
+                    entry(7 * 60, true, true, Some("Beta")),
+                    entry(22 * 60, true, true, Some("Alpha")),
+                    entry(15 * 60, true, true, Some("Beta")),
+                ])
+            });
+        assert!(BillCommand::execute(client, None, None).await.is_ok());
+    }
+}
